window.STORY_CHAPTERS["cb12946617b1753f8"]={"id":"cb12946617b1753f8","lines":[{"uid":"talk.ch3_4_1001#originalText","id":"talk.ch3_4_1001","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"怎么大家都知道了？","en":"How did word spread so fast?","ja":"いつの間に広まったんだ?"},"kind":"dialogue"},{"uid":"talk.ch3_4_1002#originalText","id":"talk.ch3_4_1002","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人！ 你做了什么事啊！","en":"Kirito! What have you done?","ja":"キリト!何やらかしたんだよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_1003#originalText","id":"talk.ch3_4_1003","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没啦……哈哈哈。","en":"Uhh...hahaha?","ja":"いや～…ははは"},"kind":"dialogue"},{"uid":"talk.ch3_4_1004#originalText","id":"talk.ch3_4_1004","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……不对，你这一年来 基本上没惹出什么大麻烦， 已经算是奇迹了。","en":"Actually...it's a miracle you haven't caused any problems this past year.","ja":"……いや、キリトが1年間いちおうは何も問題を起こさなかったのが奇跡なんだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_1005#originalText","id":"talk.ch3_4_1005","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不愧是跟我相处已久的伙伴！","en":"After all those years, you sure know me well, partner!","ja":"さすが!長い付き合いだけのことはあるな、相棒"},"kind":"dialogue"},{"uid":"talk.ch3_4_1006#originalText","id":"talk.ch3_4_1006","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"利邦提同学， 这到底是怎么回事？","en":"Levantein, what is the meaning of this?","ja":"リーバンテイン殿これはどういうことだ?"},"kind":"dialogue"},{"uid":"talk.ch3_4_1007#originalText","id":"talk.ch3_4_1007","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"妳的随侍做了一些失礼的事。","en":"Your page was a bit disrespectful to me.","ja":"そなたの傍付きにちょっとした逸礼行為があってね"},"kind":"dialogue"},{"uid":"talk.ch3_4_1008#originalText","id":"talk.ch3_4_1008","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"我也不想严厉地惩罚他， 让他用真剑和我比试一场就好。","en":"Since a serious punishment is not warranted, we'll settle it with the sword.","ja":"大仰な懲罰を科すのもどうかと思ったので実剣での立ち合い一本で済ませるつもりだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_1009#originalText","id":"talk.ch3_4_1009","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你说什么！","en":"What?","ja":"なんだと"},"kind":"dialogue"},{"uid":"talk.ch3_4_1010#originalText","id":"talk.ch3_4_1010","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"学姊，抱歉让妳担心了。","en":"Sorry I worried you, Liena.","ja":"ご心配おかけしてすみません、先輩"},"kind":"dialogue"},{"uid":"talk.ch3_4_1011#originalText","id":"talk.ch3_4_1011","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过，我没问题的。","en":"But I'll be okay.","ja":"でも、俺なら大丈夫です"},"kind":"dialogue"},{"uid":"talk.ch3_4_1011_2#originalText","id":"talk.ch3_4_1011_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"反倒是……能和首席交手， 我觉得非常幸运。","en":"If anything... I'm honored to spar with the First Seat.","ja":"むしろ……主席殿と手合わせできるのは幸運なことと思っていますから"},"kind":"dialogue"},{"uid":"talk.ch3_4_1012#originalText","id":"talk.ch3_4_1012","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人…… 比试的输赢要怎么算？","en":"Kirito...what are the rules of your duel?","ja":"キリト……立ち合いの決めはどうなっている"},"kind":"dialogue"},{"uid":"talk.ch3_4_1013#originalText","id":"talk.ch3_4_1013","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦……因为要使用真剑， 所以应该和练习一样是点到为止……","en":"Huh? Since we're using real swords, I assume we’re stopping short...","ja":"え……実剣を使用するので稽古と同様に寸止めなのではと……"},"kind":"dialogue"},{"uid":"talk.ch3_4_1014#originalText","id":"talk.ch3_4_1014","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"啊，我忘记说了。","en":"Oh, yes. I forgot to tell you.","ja":"ああ、言い忘れていたな"},"kind":"dialogue"},{"uid":"talk.ch3_4_1015#originalText","id":"talk.ch3_4_1015","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"我从来不进行点到为止的比试。进行私人比试时， 一定是先击中对方的人获胜。","en":"I don't stop short in duels. All my duels are decided by first blood.","ja":"私は、寸止めの立ち合いはしないのだ個人的な試合は全て一本先取を決めにしている"},"kind":"dialogue"},{"uid":"talk.ch3_4_1016#originalText","id":"talk.ch3_4_1016","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人从来没有跟人用真剑比试过！","en":"But Kirito has never dueled with a real sword before!","ja":"キリトは実剣での立ち合いなどしたことがないのだぞ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_1017#originalText","id":"talk.ch3_4_1017","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"当然，这要双方同意才行。","en":"Indeed. This duel requires mutual consent.","ja":"ああ。もっとも双方の合意がなくては行えない"},"kind":"dialogue"},{"uid":"talk.ch3_4_1018#originalText","id":"talk.ch3_4_1018","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"如果你拒绝， 那也只能点到为止了…… 桐人练士，就交给你选择吧。","en":"If you refuse, we will resort to stopping short... It's your choice, Kirito.","ja":"お前が拒むのなら寸止めもやむなしだな……選択は任せよう、キリト練士"},"kind":"dialogue"},{"uid":"talk.ch3_4_1019#originalText","id":"talk.ch3_4_1019","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人，你就拒绝吧。涡罗很强，那太危险了。","en":"Don't do it, Kirito! Volo is too powerful. It's dangerous.","ja":"止めておけ、キリトウォロは強い。危険すぎる"},"kind":"dialogue"},{"uid":"talk.ch3_4_1020#originalText","id":"talk.ch3_4_1020","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……利邦提学长，规则就交由你决定， 因为我是接受惩罚的人啊。","en":"I'll let you set the parameters, Levantein. After all, I'm the one being punished.","ja":"……方法はお任せします、リーバンテイン殿俺は懲罰を受ける身ですから"},"kind":"dialogue"},{"uid":"talk.ch3_4_1021#originalText","id":"talk.ch3_4_1021","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人。","en":"Kirito.","ja":"キリト"},"kind":"dialogue"},{"uid":"talk.ch3_4_1022#originalText","id":"talk.ch3_4_1022","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉、莉娜学姊……","en":"L-Liena...","ja":"リ、リーナ先輩……"},"kind":"dialogue"},{"uid":"talk.ch3_4_1023#originalText","id":"talk.ch3_4_1023","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"桐人，我相信你的实力， 但就是因为相信才要告诉你。","en":"Kirito, I believe in your power... so let me give you a tip.","ja":"キリト、私はお前の強さを信じる信じるがゆえに教えておく"},"kind":"dialogue"},{"uid":"talk.ch3_4_1024#originalText","id":"talk.ch3_4_1024","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"涡罗的利邦提家有个 不为人知的家训。","en":"House Levantein has a sacred saying:","ja":"ウォロのリーバンテイン家には秘めたる家訓がある"},"kind":"dialogue"},{"uid":"talk.ch3_4_1025#originalText","id":"talk.ch3_4_1025","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"《只有沾染强者之血的剑， 才能增加己身实力》。","en":"\"Wet thy sword in the blood of the mighty to gain their power\"...","ja":"《剣を強者の血に濡らせ、されば強さは我が物とならん》"},"kind":"dialogue"},{"uid":"talk.ch3_4_1026#originalText","id":"talk.ch3_4_1026","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"血……是吗？","en":"Blood...you say?","ja":"……血、ですか"},"kind":"dialogue"},{"uid":"talk.ch3_4_1027#originalText","id":"talk.ch3_4_1027","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"没错，涡罗应该在入学之前 应该已经进行过好几次 初击胜利的真剑比试了。","en":"Yes. Volo had fought in many duels with real swords before entering the Academy.","ja":"そうだ。ウォロは入学以前にも実剣による一本先取勝負を幾度となく行っているはずだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_1028#originalText","id":"talk.ch3_4_1028","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（我懂了，是《想像的力量》吗。）","en":"(I get it, the power of imagination.)","ja":"(そうか、《イメージの力》か)"},"kind":"dialogue"},{"uid":"talk.ch3_4_1029#originalText","id":"talk.ch3_4_1029","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（《让剑吸取越多强敌的鲜血， 就会越强大》的家训 赋予了涡罗的剑力量……）","en":"(The belief that \"strong blood makes your sword strong\" actually made Volo's sword stronger.)","ja":"(《剣に強敵の血を吸わせれば吸わせるほど強くなる》という家訓がウォロの剣に力を与えている……)"},"kind":"dialogue"},{"uid":"talk.ch3_4_1030#originalText","id":"talk.ch3_4_1030","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"他也打算把你的剑的力量化为鲜血， 作为粮食汲取。","en":"He's planning on absorbing your blood into his sword to strengthen it.","ja":"奴は、お前の剣力をも血に変えて吸い取り、糧とするつもりだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_1031#originalText","id":"talk.ch3_4_1031","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"但是，我再说一次， 我对你有信心。你绝对不是那种 会被他轻易吞噬的剑士。","en":"Let me repeat, I believe that you will not let him easily do you in.","ja":"しかし、繰り返すが、私はお前を信じているあやつに容易く喰われるような剣士ではない、とな"},"kind":"dialogue"},{"uid":"talk.ch3_4_1032#originalText","id":"talk.ch3_4_1032","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……你应该没忘记昨天 和我约定好的事吧？","en":"Do you remember the promise you made me yesterday?","ja":"……昨日、私に約束したことを忘れてはいないだろう?"},"kind":"dialogue"},{"uid":"talk.ch3_4_1033#originalText","id":"talk.ch3_4_1033","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯，我和学姊约好要展现 自己所有的实力。","en":"Yes. I promised I would show you everything I'm made of.","ja":"ええ俺の全てを先輩に見せると約束しました"},"kind":"dialogue"},{"uid":"talk.ch3_4_1034#originalText","id":"talk.ch3_4_1034","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"那就在这里展现吧，桐人。","en":"Then show me now, Kirito.","ja":"ならば、ここで見せてくれ、キリト"},"kind":"dialogue"},{"uid":"talk.ch3_4_1035#originalText","id":"talk.ch3_4_1035","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"把你所拥有的力量与技巧全部解放， 赢过涡罗‧利邦提。","en":"Draw upon all the skill and power at your disposal and defeat Volo Levantein.","ja":"お前の持てる力と技の全てを解き放ちウォロ・リーバンテインに勝て"},"kind":"dialogue"},{"uid":"talk.ch3_4_1036#originalText","id":"talk.ch3_4_1036","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好， 我会履行诺言的。","en":"I will uphold my promise.","ja":"はい約束、果たしてきます"},"kind":"dialogue"},{"uid":"talk.ch3_4_4400#originalText","id":"talk.ch3_4_4400","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（啧，只是掠过而已吗…… 毕竟第四击不是突进技……）","en":"(I only grazed him... Well, my fourth attack isn't a rush...)","ja":"(くっ、掠めただけか……四撃目は突進技じゃないからな……)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4401#originalText","id":"talk.ch3_4_4401","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"到此为止！！","en":"That's enough!!","ja":"そこまで!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4402#originalText","id":"talk.ch3_4_4402","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"阿、阿滋利卡老师？","en":"M-Ms. Azurika?","ja":"ア、アズリカ先生?"},"kind":"dialogue"},{"uid":"talk.ch3_4_4403#originalText","id":"talk.ch3_4_4403","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"既然是那位女士的裁决， 那也只能遵从了。","en":"We're going to have to follow her ruling.","ja":"あの方の裁定ならば従わぬわけにはいくまい"},"kind":"dialogue"},{"uid":"talk.ch3_4_4404#originalText","id":"talk.ch3_4_4404","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……那、那个……为什么？","en":"B-but...why?","ja":"……え、ええと……なぜです?"},"kind":"dialogue"},{"uid":"talk.ch3_4_4405#originalText","id":"talk.ch3_4_4405","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"因为那位女士 在七年前的四帝国统一大会里，","en":"Because she was Norlangarth Empire’s first sword","ja":"あの方は7年前の四帝国統一大会における"},"kind":"dialogue"},{"uid":"talk.ch3_4_4406#originalText","id":"talk.ch3_4_4406","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"是诺兰卡鲁斯北帝国 的第一代表剑士。","en":"...in the Unification Tournament seven years ago.","ja":"ノーランガルス北帝国第1代表剣士だからだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_4407#originalText","id":"talk.ch3_4_4407","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"什么！？","en":"Huh?!","ja":"ええ!?"},"kind":"dialogue"},{"uid":"talk.ch3_4_4408#originalText","id":"talk.ch3_4_4408","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"桐人练士的惩罚到此结束。","en":"Trainee Kirito, your punishment has officially ended.","ja":"キリト練士の懲罰はこれにて終了とする"},"kind":"dialogue"},{"uid":"talk.ch3_4_4409#originalText","id":"talk.ch3_4_4409","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"今后你要小心别再把泥巴 溅到别人身上了。","en":"Take care not to soil a person's clothes in the future.","ja":"今後は、誰かに泥を跳ね飛ばさぬよう気をつけることだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_4500_0#originalText","id":"talk.ch3_4_4500_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"与涡罗比试后","en":"After the Duel with Volo","ja":"ウォロとの立ち合い後"},"kind":"caption"},{"uid":"talk.ch3_4_4500#originalText","id":"talk.ch3_4_4500","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（剑恢复到原来的大小了……）","en":"(My sword is back to its normal size.)","ja":"(剣が元の大きさに戻ってる……)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4501#originalText","id":"talk.ch3_4_4501","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"！？莉娜学姊？","en":"Liena?","ja":"!? リーナ先輩?"},"kind":"dialogue"},{"uid":"talk.ch3_4_4502#originalText","id":"talk.ch3_4_4502","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"…………我还以为你会被砍中。","en":"I thought you'd been cut...","ja":"…………斬られた、と思ったぞ"},"kind":"dialogue"},{"uid":"talk.ch3_4_4503#originalText","id":"talk.ch3_4_4503","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯……我也以为会这样。","en":"Yeah...I thought so too.","ja":"ええ……俺もそう思いました"},"kind":"dialogue"},{"uid":"talk.ch3_4_4504#originalText","id":"talk.ch3_4_4504","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"…………可是你没有投降………… 你这个大笨蛋！","en":"But you didn't surrender... you bumbling idiot!","ja":"…………なのに降参しないとは…………この、大馬鹿者め"},"kind":"dialogue"},{"uid":"talk.ch3_4_4505#originalText","id":"talk.ch3_4_4505","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"干得好……你的表现非常精彩呢， 桐人。","en":"Incredible... Your swordsmanship was amazing, Kirito.","ja":"見事な……素晴らしい戦いぶりだったぞ、キリト"},"kind":"dialogue"},{"uid":"talk.ch3_4_4506#originalText","id":"talk.ch3_4_4506","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我要向你道谢。虽然很可惜，没办法一个人独占。","en":"Thank you. It's a pity I had to share the moment with an audience,","ja":"礼を言わせてもらうよ独り占めできなかったのは残念だが"},"kind":"dialogue"},{"uid":"talk.ch3_4_4507#originalText","id":"talk.ch3_4_4507","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……你已遵守承诺， 让我见识到你全力一战的模样…… 谢谢你。","en":"but you kept your promise. You showed me the best fight of your life... Thank you.","ja":"……お前は、約束どおり私に全力の戦いを見せてくれた……ありがとう"},"kind":"dialogue"},{"uid":"talk.ch3_4_4508#originalText","id":"talk.ch3_4_4508","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦…… 但、但只是平手……","en":"Huh? B-but it was technically a tie.","ja":"えっ……で、でも、引き分けですし……"},"kind":"dialogue"},{"uid":"talk.ch3_4_4509#originalText","id":"talk.ch3_4_4509","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"能够和那个利邦提战成平手， 你还有什么不满吗？","en":"A tie, against Levantein, is not enough for you?","ja":"あのリーバンテイン相手に引き分けておいて不満か?"},"kind":"dialogue"},{"uid":"talk.ch3_4_4510#originalText","id":"talk.ch3_4_4510","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不、不是啦……","en":"Oh, n-no, that's not what I meant.","ja":"い、いえ、そういうわけじゃ"},"kind":"dialogue"},{"uid":"talk.ch3_4_4511#originalText","id":"talk.ch3_4_4511","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这已经不是谁胜谁败的问题了。","en":"Winning or losing doesn't matter.","ja":"もはや勝ち負けは問題ではないよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_4511_2#originalText","id":"talk.ch3_4_4511_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你战斗的模样…… 让我学习到相当重要的东西。","en":"I learned something very important, watching you fight.","ja":"お前の戦いぶりに、私は大切な……とても大切なものを学んだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_4512#originalText","id":"talk.ch3_4_4512","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"到我的房间里喝点东西庆祝一下吧。","en":"Let's have a little celebration in my room!","ja":"私の部屋で、軽く祝杯を上げようじゃないか"},"kind":"dialogue"},{"uid":"talk.ch3_4_4512_2#originalText","id":"talk.ch3_4_4512_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"把尤吉欧和哥鲁哥罗索同学 也叫过来吧。","en":"Invite Eugeo and Golgorosso.","ja":"ユージオとゴルゴロッソ殿も呼ぶとしようか"},"kind":"dialogue"},{"uid":"talk.ch3_4_4513#originalText","id":"talk.ch3_4_4513","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好！","en":"Sure!","ja":"はい!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4514#originalText","id":"talk.ch3_4_4514","speaker":{"cn":"莱欧斯‧温贝尔","en":"Raios/Humbert","ja":"ライオス・ウンベール"},"text":{"cn":"……","en":"......","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch3_4_4515#originalText","id":"talk.ch3_4_4515","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"……","en":"......","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5000#originalText","id":"talk.ch3_4_5000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"上级修剑士宿舍‧索尔缇莉娜的房间","en":"Elite Disciples' Dorm - Sortiliena's Room","ja":"上級修剣士寮・ソルティリーナの部屋"},"kind":"caption"},{"uid":"talk.ch3_4_5001#originalText","id":"talk.ch3_4_5001","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天看了那场比试，我再次觉得……","en":"It struck me again, watching today's duel.","ja":"今日の立ち合いを見て改めて思ったよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5002#originalText","id":"talk.ch3_4_5002","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你的艾恩葛朗特流真是深不可测。","en":"Your Aincrad style has endless potential.","ja":"お前のアインクラッド流は底が知れないな"},"kind":"dialogue"},{"uid":"talk.ch3_4_5002_2#originalText","id":"talk.ch3_4_5002_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我的赛鲁鲁特流也算是实用剑术， 但还是太过僵硬。","en":"My own Serlut style is too rigid in comparison.","ja":"我がセルルト流も実用剣術のつもりでいたがまだまだ堅い"},"kind":"dialogue"},{"uid":"talk.ch3_4_5003#originalText","id":"talk.ch3_4_5003","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"妳还在提这个啊。我可从来没有打赢过学姊妳呢。","en":"There you go again... I haven't beaten you once!","ja":"またその話ですか俺は先輩に勝てたことがないんですよ?"},"kind":"dialogue"},{"uid":"talk.ch3_4_5004#originalText","id":"talk.ch3_4_5004","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"赛鲁鲁特流在攻击上变化多端， 真的只能用精彩来形容。","en":"The variety of attacks in the Serlut style is nothing less than beautiful.","ja":"セルルト流の攻撃の多彩さは本当に見事と言うしかありません"},"kind":"dialogue"},{"uid":"talk.ch3_4_5005#originalText","id":"talk.ch3_4_5005","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"老实说，桐人……","en":"Listen, Kirito...","ja":"実はな、キリト……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5005_2#originalText","id":"talk.ch3_4_5005_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我们赛鲁鲁特家的先祖 曾经得罪过皇帝，","en":"An ancestor of mine greatly displeased the Emperor.","ja":"我がセルルト家は遠い祖先が皇帝の不興を買ったがゆえに"},"kind":"dialogue"},{"uid":"talk.ch3_4_5006#originalText","id":"talk.ch3_4_5006","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"所以被禁止学习正统剑术 《海伊‧瑙鲁基亚流》。","en":"As such, we're forbidden from learning the High-Norkian style.","ja":"正統剣術たる《ハイ・ノルキア流》の伝承を禁じられているのだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5007#originalText","id":"talk.ch3_4_5007","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦……","en":"Huh?","ja":"え……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5008#originalText","id":"talk.ch3_4_5008","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"因此，只能使用实战性…… 不对，是只能练一些非正统的剑术，","en":"So we had to hone practical... rather, unorthodox sword skills, instead.","ja":"そのため実戦的……いや変則的な剣術を磨くしかなかった"},"kind":"dialogue"},{"uid":"talk.ch3_4_5008_2#originalText","id":"talk.ch3_4_5008_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"那就是赛鲁鲁特流。","en":"That is the Serlut style.","ja":"それがセルルト流だ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5009#originalText","id":"talk.ch3_4_5009","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我并不觉得有什么不满。不如说，我一直都以自己的流派为荣。","en":"But I don't feel bitter about it. If anything, I'm proud of our style.","ja":"不満に思っているわけではないむしろ私は我が流派を誇りとしてきた"},"kind":"dialogue"},{"uid":"talk.ch3_4_5010#originalText","id":"talk.ch3_4_5010","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……不过， 也许我的内心深处 还是觉得迷惘吧。","en":"However...a part of me is probably conflicted, deep inside.","ja":"……だが心のどこかには迷いがあったのかもしれない"},"kind":"dialogue"},{"uid":"talk.ch3_4_5011#originalText","id":"talk.ch3_4_5011","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这两年里无法超越传承了 海伊‧瑙鲁基亚流的涡罗，","en":"That might be why I could never defeat Volo.","ja":"2年間、ハイ・ノルキア流を伝承しているウォロを凌駕し得なかったのは"},"kind":"dialogue"},{"uid":"talk.ch3_4_5011_2#originalText","id":"talk.ch3_4_5011_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"可能也是因为那样……","en":"He inherited the High-Norkian style I could not.","ja":"それゆえだったのかもしれないな……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5012#originalText","id":"talk.ch3_4_5012","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"学姊……","en":"Liena...","ja":"先輩……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5013#originalText","id":"talk.ch3_4_5013","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"但是，你不一样。","en":"But, you're different.","ja":"だが、お前は違う"},"kind":"dialogue"},{"uid":"talk.ch3_4_5014#originalText","id":"talk.ch3_4_5014","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"虽然同样是独特流派的剑士， 面对正统流派的人， 你却完全都不会感到自卑。","en":"You also wield a unique style, yet you do not feel inferior to those of the traditional schools.","ja":"同じように独自流派の使い手でありながら正統流派の者たちにまるで引け目を感じていない"},"kind":"dialogue"},{"uid":"talk.ch3_4_5015#originalText","id":"talk.ch3_4_5015","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这一年我在你身边观察……","en":"Watching you this year,","ja":"1年間傍で見てきて……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5015_2#originalText","id":"talk.ch3_4_5015_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"然后，今天又看你和涡罗交手， 我终于知道原因在哪里了。","en":"as my page... and seeing you duel Volo today, I finally know why.","ja":"そして今日のウォロとの立ち合いを見てその理由がようやく解った気がしているよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5016#originalText","id":"talk.ch3_4_5016","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……","en":"......","ja":"……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5017#originalText","id":"talk.ch3_4_5017","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"身为赛鲁鲁特流的继承人， 我现在从心里感到骄傲…… 然后，也觉得很高兴。","en":"I am proud and I am happy to be the successor to the Serlut style.","ja":"私は、私がセルルト流の後継者であることをいま心の底から誇りに……そして嬉しく思っている"},"kind":"dialogue"},{"uid":"talk.ch3_4_5018#originalText","id":"talk.ch3_4_5018","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"……我也很高兴能成为你的指导生。","en":"I feel the same pride and joy being your mentor...got that?","ja":"……お前の指導生となれたことも、な"},"kind":"dialogue"},{"uid":"talk.ch3_4_5019#originalText","id":"talk.ch3_4_5019","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉娜学姊， 最后的修剑士检定比试， 请妳一定要打败涡罗首席。","en":"Liena. I hope you're the one to defeat Volo at the final ranking exam match.","ja":"リーナ先輩。最後の修剣士検定試合今度は先輩がウォロ主席に勝ってください"},"kind":"dialogue"},{"uid":"talk.ch3_4_5020#originalText","id":"talk.ch3_4_5020","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"好。","en":"Thanks.","ja":"ああ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5021#originalText","id":"talk.ch3_4_5021","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"初等练士宿舍‧西侧花坛","en":"Primary Trainees' Dorm - West Flower Bed","ja":"初等練士寮・西の花壇"},"kind":"caption"},{"uid":"talk.ch3_4_5022#originalText","id":"talk.ch3_4_5022","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"哎唷，你来得正好， 我们现在正打算去找你呢。","en":"Oh, perfect timing. I was just about to go looking for you.","ja":"おやおや、ちょうど良かった。今から、貴殿を捜しに行こうと思っていたところだったのだよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5023#originalText","id":"talk.ch3_4_5023","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……你们有什么事？","en":"What do you want?","ja":"……何の用だ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5024#originalText","id":"talk.ch3_4_5024","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"当然是为了称赞你精彩的表现。","en":"What else? To commend your exemplary performance earlier.","ja":"無論、貴殿の見事な戦いぶりに賛辞を贈ろうと思ってな"},"kind":"dialogue"},{"uid":"talk.ch3_4_5025#originalText","id":"talk.ch3_4_5025","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"不过，面对那种像杂耍一样的剑术， 就算是首席， 多少也会有点措手不及吧。","en":"You were like a circus performer out there. No wonder Volo was a little unnerved.","ja":"ま、あのような曲芸じみた剣術にはさしもの主席殿も多少面食らったというところですかなあ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5026#originalText","id":"talk.ch3_4_5026","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你们是来找我吵架的吗？","en":"Are you picking a fight?","ja":"喧嘩を売ってるのか?"},"kind":"dialogue"},{"uid":"talk.ch3_4_5027#originalText","id":"talk.ch3_4_5027","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"绝无此事！ 高等贵族绝不会找平民挑衅。","en":"Don't be silly! Noblemen never pick anything.","ja":"とんでもない! 上級貴族は、決して平民に何かを売ったりはしないのだよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5028#originalText","id":"talk.ch3_4_5028","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"我们只会施舍，哈哈哈。","en":"That would be more your role. Hahaha!","ja":"施すことはあってもな、ハハハ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5029#originalText","id":"talk.ch3_4_5029","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"呵呵呵呵呵。","en":"Hehehe!","ja":"クックックックック"},"kind":"dialogue"},{"uid":"talk.ch3_4_5030#originalText","id":"talk.ch3_4_5030","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"我就称赞一下你的杂耍…… 不对，是英勇，把这个给你吧。好好收下吧。","en":"A little token, in honor of your circus tricks...er, your valiant skills.","ja":"貴殿の曲芸……いや、健闘を称えこれを進呈しよう。受け取ってくれたまえ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5031#originalText","id":"talk.ch3_4_5031","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"……那我们就先失陪了。晚安，桐人同学。","en":"Well, we must take our leave now. Goodnight, Sir Kirito.","ja":"……では、我々はこれにて失礼するおやすみ、キリト殿"},"kind":"dialogue"},{"uid":"talk.ch3_4_5032#originalText","id":"talk.ch3_4_5032","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"你可别太嚣张。","en":"Don't get cocky, peasant!","ja":"いい気になるなよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5033#originalText","id":"talk.ch3_4_5033","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………啊、啊啊………… 赛菲利雅的花蕾……","en":"O-ohhh... My Zephyria buds...","ja":"…………あ、ああ…………ゼフィリアの蕾が……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5034#originalText","id":"talk.ch3_4_5034","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"一开始只是个实验。","en":"At first, it was just an experiment.","ja":"はじめは、ただの実験だった"},"kind":"dialogue"},{"uid":"talk.ch3_4_5035#originalText","id":"talk.ch3_4_5035","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"据说赛菲利雅之花在这个国家 绝对不会开花。","en":"They say Zephyria flowers can't bloom in Norlangarth's soil....","ja":"この国では決して咲かないと言われているゼフィリアの花"},"kind":"dialogue"},{"uid":"talk.ch3_4_5036#originalText","id":"talk.ch3_4_5036","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉娜学姊说她很喜欢那种花， 我就想实验能不能用我的想像力 使其开花。","en":"I would use my imagination to bloom the flowers Liena loves so much.","ja":"リーナ先輩が好きだと言っていたその花を俺のイメージ力だけで咲かせることができるのかどうか"},"kind":"dialogue"},{"uid":"talk.ch3_4_5037#originalText","id":"talk.ch3_4_5037","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"可是，不知何时……","en":"Before I realized it...","ja":"でも俺はいつしか……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5037_2#originalText","id":"talk.ch3_4_5037_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我把这些拼命要在异国土地绽放的 花朵，和自己的身影重叠了。","en":"I saw myself in these displaced flowers.","ja":"異国の土で懸命に咲こうとしているこの花たちに自分自身を重ねていたんだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5038#originalText","id":"talk.ch3_4_5038","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我希望借由这些花朵， 分担自己……","en":"I'm displaced from my own world... from the people I love so much.","ja":"現実世界から……親しい、愛しい人々から切り離され"},"kind":"dialogue"},{"uid":"talk.ch3_4_5039#originalText","id":"talk.ch3_4_5039","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"和现实世界最亲近、最爱的人们分离， 而且不知道何时才能再相见的 寂寞与痛苦……","en":"I thought the flowers could share the grief of never knowing when I'll see them again.","ja":"いつ再会できるかも解らない寂しさや苦しさを花たちと分かち合おうとしていたんだ……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5040#originalText","id":"talk.ch3_4_5040","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"………………对不起…………","en":"I'm so sorry.","ja":"………………ごめんよ…………"},"kind":"dialogue"},{"uid":"talk.ch3_4_5041#originalText","id":"talk.ch3_4_5041","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"唔……呜……","en":"*S-Sniff*...","ja":"く……うぅ……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5042#originalText","id":"talk.ch3_4_5042","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"相信它们吧。","en":"Have faith.","ja":"信じなさい"},"kind":"dialogue"},{"uid":"talk.ch3_4_5043#originalText","id":"talk.ch3_4_5043","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"相信这些在异国成长到 这种地步的花朵的力量。","en":"Believe in the power of your flowers, grown in foreign soil.","ja":"異国の土でここまで育った花たちの力を"},"kind":"dialogue"},{"uid":"talk.ch3_4_5044#originalText","id":"talk.ch3_4_5044","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"也要相信把这些花朵栽培到 这种程度的自己的力量。","en":"And believe in yourself... You who nurtured these flowers this far.","ja":"そして、その花をここまで育てたあなた自身の力を"},"kind":"dialogue"},{"uid":"talk.ch3_4_5045#originalText","id":"talk.ch3_4_5045","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……但是，它们…… 它们全都死掉了啊。","en":"But...they've all died.","ja":"……でも、もう……みんな、死んでしまった"},"kind":"dialogue"},{"uid":"talk.ch3_4_5046#originalText","id":"talk.ch3_4_5046","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"别担心。扎在土里成长的根还想要活下去。","en":"Fear not. Their roots beneath the soil still wish to live.","ja":"大丈夫土に張った根はまだ生きようとしているわ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5047#originalText","id":"talk.ch3_4_5047","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"而且……你也能感觉到吧？","en":"Can’t you feel it?","ja":"それに……感じるでしょう? "},"kind":"dialogue"},{"uid":"talk.ch3_4_5047_2#originalText","id":"talk.ch3_4_5047_2","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"开在这座花坛里的无数圣花们， 都想帮助它们的小小伙伴。","en":"The sacred flowers in this garden want to help their sisters bloom.","ja":"この花壇に咲くたくさんの聖花たちが小さな仲間を助けたいと思っているのを"},"kind":"dialogue"},{"uid":"talk.ch3_4_5048#originalText","id":"talk.ch3_4_5048","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……我办不到啊。我根本没办法使用那么高级的神圣术。","en":"I can't. I'm not powerful in the Sacred Arts.","ja":"……無理だ俺にはそんな高等な神聖術は使えない"},"kind":"dialogue"},{"uid":"talk.ch3_4_5049#originalText","id":"talk.ch3_4_5049","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"所有的术式都只不过是道具， 用来引导、调整《心意》……","en":"The Sacred Arts are about \"will.\"","ja":"あらゆる術式は、《シンイ》……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5049_2#originalText","id":"talk.ch3_4_5049_2","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"也就是你说的想像力。","en":"They are merely tools to manifest your imagination.","ja":"あなたの言うイメージを導き整えるための道具に過ぎないわ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5050#originalText","id":"talk.ch3_4_5050","speaker":{"cn":"？？？","en":"???","ja":"？？？"},"text":{"cn":"来，感受花朵们的祈祷── 感受这个世界的真理……","en":"Come. Feel the prayers of the flowers. Feel the laws of nature.","ja":"さあ感じて、花たちの祈りを――世界の、ことわりを……"},"kind":"dialogue"},{"uid":"talk.ch3_4_6009#originalText","id":"talk.ch3_4_6009","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"上级修剑士宿舍‧桐人与尤吉欧的房间","en":"Elite Disciples' Dorm - Kirito and Eugeo's Room","ja":"上級修剣士寮・キリトとユージオの部屋"},"kind":"caption"},{"uid":"talk.ch3_4_6010#originalText","id":"talk.ch3_4_6010","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"报告尤吉欧上级修剑士！ 今日的打扫工作已经完成！","en":"Elite Disciple Eugeo! Reporting in! Today's cleaning is finished!","ja":"ユージオ上級修剣士殿、ご報告します!本日の掃除、完了いたしました!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6011#originalText","id":"talk.ch3_4_6011","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"辛苦了，缇洁。今天这样就可以了，妳回宿舍去吧。然后……那个……","en":"Thank you, Tiese. You can go back to the dorms for the day. So, uhh...","ja":"ご苦労様、ティーゼ。今日はもうこれで寮に戻っていいよ。……で、ええと……"},"kind":"dialogue"},{"uid":"talk.ch3_4_6012#originalText","id":"talk.ch3_4_6012","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……抱歉喔，罗妮耶。","en":"Sorry, Ronie.","ja":"……ごめんね、ロニエ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6013#originalText","id":"talk.ch3_4_6013","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我明明已经跟那家伙说过好几次， 在妳打扫好房间前一定要回来……","en":"I've told him countless times to be back by the time you finish cleaning the room.","ja":"あいつには何度も、部屋の掃除が終わるまでに戻ってこいって言ってあるんだけど……"},"kind":"dialogue"},{"uid":"talk.ch3_4_6014#originalText","id":"talk.ch3_4_6014","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"没、没关系， 在这里待到报告完毕是随侍的任务！","en":"Oh, n-no! My duties don't end until I've delivered my report.","ja":"い、いえ報告を完了するまでが傍付きの任務ですから!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6015#originalText","id":"talk.ch3_4_6015","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……我可以帮妳跟他说一下， 还是叫他把随侍换成别人吧……","en":"Maybe you want to pick a different mentor? I can put in a word for you.","ja":"……僕から言ってあげるから傍付きを他の人に代わってもらってもいいんじゃないかな……"},"kind":"dialogue"},{"uid":"talk.ch3_4_6016#originalText","id":"talk.ch3_4_6016","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要是跟着那个家伙， 这一年一定会过得很辛苦。","en":"If you're his page, you'll suffer the entire year.","ja":"アイツに付いてると1年間苦労するよ、間違いなく"},"kind":"dialogue"},{"uid":"talk.ch3_4_6017#originalText","id":"talk.ch3_4_6017","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"千、千万别这么说！","en":"N-no, it's no problem at all!","ja":"と、とんでもありません!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6018#originalText","id":"talk.ch3_4_6018","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂喂， 你趁别人不在，在那边说什么啊。","en":"Hey. Gossiping about me while I'm gone?","ja":"おいおい人の留守に何を言ってるんだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6019#originalText","id":"talk.ch3_4_6019","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"报告桐人上级修剑士！ 本日的清扫已经顺利完成！","en":"Elite Disciple Kirito! Reporting in, today's cleaning is finished!","ja":"キリト上級修剣士殿、ご報告します!本日の清掃、滞りなく完了しました!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6020#originalText","id":"talk.ch3_4_6020","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好的，辛苦了。","en":"Great, thanks!","ja":"はい、お疲れさま"},"kind":"dialogue"},{"uid":"talk.ch3_4_6021#originalText","id":"talk.ch3_4_6021","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我说桐人，","en":"Kirito,","ja":"あのねえキリト"},"kind":"dialogue"},{"uid":"talk.ch3_4_6021_2#originalText","id":"talk.ch3_4_6021_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"她们比你还要忙好几倍， 你要在打扫完成之前回来啦。","en":"they work ten times as hard as we do. At least be here when they finish cleaning.","ja":"彼女たちはお前の何倍も忙しいんだから掃除が終わるまでには戻ってきてやりなよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6022#originalText","id":"talk.ch3_4_6022","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"而且， 为什么你非得从窗户回来啊？","en":"And why did you come back through the window, anyway?","ja":"だいたい、なんで窓から帰ってこなきゃならないんだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6023#originalText","id":"talk.ch3_4_6023","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"因为从东三街回来时， 走这窗户是最近的啊。","en":"This window is the shortest distance from East Third Street.","ja":"東3番通りから帰ってくるときはこの窓が最短コースなんだよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6024#originalText","id":"talk.ch3_4_6024","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"罗妮耶和缇洁最好也记一下， 将来会有帮助的。","en":"Take note, Ronie, Tiese. It will save you both time.","ja":"ロニエとティーゼも覚えておくと将来役に立つぞ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6025#originalText","id":"talk.ch3_4_6025","speaker":{"cn":"罗妮耶‧缇洁","en":"Ronie/Tiese","ja":"ロニエ・ティーゼ"},"text":{"cn":"好、好的！","en":"Y-yes, sir!","ja":"は、はい!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6026#originalText","id":"talk.ch3_4_6026","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你别乱教她们啦！ ……东三街，也就是说那个袋子是……","en":"Don't fill their heads with nonsense! And East Third Street? What's in the bag?","ja":"妙なこと吹き込むなよ!……東3番通りってことは、その袋は……"},"kind":"dialogue"},{"uid":"talk.ch3_4_6027#originalText","id":"talk.ch3_4_6027","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哼哼， 想吃就老实说啊， 尤吉欧同学。","en":"Hehehe. If you want some, just ask me nicely, Eugeo, my boy!","ja":"ふふん、欲しければ素直にそう言いたまえよユージオ君"},"kind":"dialogue"},{"uid":"talk.ch3_4_6028#originalText","id":"talk.ch3_4_6028","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"来，回到宿舍之后， 和妳们的室友一起吃吧。","en":"Here, share these with your roommates.","ja":"はい。寮に戻ったら部屋の皆で食べろよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6029#originalText","id":"talk.ch3_4_6029","speaker":{"cn":"罗妮耶‧缇洁","en":"Ronie/Tiese","ja":"ロニエ・ティーゼ"},"text":{"cn":"哇！","en":"Ooh!","ja":"わあっ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6030#originalText","id":"talk.ch3_4_6030","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"真、真是太感谢你了， 上级修剑士大人！","en":"Thank you so much, Elite Disciples!","ja":"あ、ありがとうございます上級修剣士どの!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6031#originalText","id":"talk.ch3_4_6031","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"为了不让收到的物品天命减少， 我们会全速赶回宿舍！ 那么，明天见了！","en":"We will run full speed back to the dorms to ensure they stay fresh! See you tomorrow!","ja":"頂いた物資の天命が減少しないよう全速で寮に戻ります! それではまた明日!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6032#originalText","id":"talk.ch3_4_6032","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"果然没错！ 是跳鹿亭的蜂蜜派！","en":"I knew it! These are honey pies from Deer Diner!","ja":"やっぱり!跳ね鹿亭の蜂蜜パイだよ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6033#originalText","id":"talk.ch3_4_6033","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"趁还热着，快回宿舍吧！","en":"Let's get these home before they get cold!","ja":"冷めないうちにはやく戻ろ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6034#originalText","id":"talk.ch3_4_6034","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……干嘛啦？","en":"What?","ja":"……なんだよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6035#originalText","id":"talk.ch3_4_6035","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我不过是在想， 桐人上级修剑士应该没有忘记 我们为什么会在这里吧？","en":"Nothing. Just hoping Elite Disciple Kirito hasn't forgotten why we're here.","ja":"キリト上級修剣士殿は、なんで僕らがここにいるのか忘れておいでじゃないでしょうね、と思っただけだよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6036#originalText","id":"talk.ch3_4_6036","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哼，我怎么可能会忘。我们可是好不容易才来到这里的。","en":"Humph. How could I forget? We've finally gotten this far.","ja":"ふん、忘れるかよようやくここまで来たんだぜ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6037#originalText","id":"talk.ch3_4_6037","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"首先要在毕业检定比试里， 赢得学院代表的宝座。","en":"First, we need to take the valedictorian spots at the graduation ranking exam.","ja":"まずは卒業検定試合で学院代表の座につく"},"kind":"dialogue"},{"uid":"talk.ch3_4_6038#originalText","id":"talk.ch3_4_6038","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"然后，要在帝国剑武大会和 四帝国统一神前大会里 一起赢得胜利。","en":"Then we need to be the last two men standing in the Four Empires Unity Tournament.","ja":"そんで、帝国剣武大会と四帝国統一神前大会でふたりとも勝ち残る"},"kind":"dialogue"},{"uid":"talk.ch3_4_6039#originalText","id":"talk.ch3_4_6039","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这么一来， 你就能成为集成骑士， 堂堂正正地由大门进入那座高塔。","en":"Then you'll become an official Integrity Knight and storm that tower.","ja":"そしたら、お前は整合騎士になれる堂々と、正面からあの塔に乗り込めるんだ"},"kind":"dialogue"},{"uid":"talk.ch3_4_6040#originalText","id":"talk.ch3_4_6040","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯…… 再一年…… 就可以……","en":"Yeah. Just one more year. Then finally...","ja":"うん……あと1年……それで、やっと……"},"kind":"dialogue"},{"uid":"talk.ch3_4_6041#originalText","id":"talk.ch3_4_6041","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"──就可以见面了。","en":"I'll finally see my blonde friend the Integrity Knight","ja":"――やっと、会える"},"kind":"dialogue"},{"uid":"talk.ch3_4_6041_2#originalText","id":"talk.ch3_4_6041_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"可以和八年前被集成骑士带走的 金发儿时玩伴见面了。","en":"took away eight years ago.","ja":"8年前、目の前で整合騎士に連れ去られた金髪の幼馴染に"},"kind":"dialogue"},{"uid":"talk.ch3_4_1000#originalText","id":"talk.ch3_4_1000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"修剑学院‧大修练场","en":"Swordcraft Academy - Main Training Hall","ja":"修剣学院・大修練場"},"kind":"caption"},{"uid":"talk.ch3_4_3000#originalText","id":"talk.ch3_4_3000","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"利邦提上级修剑士 与桐人初等练士，","en":"The one-point duel between Elite Disciple Levantein and Primary Trainee Kirito...","ja":"これより、リーバンテイン上級修剣士とキリト初等練士による"},"kind":"dialogue"},{"uid":"talk.ch3_4_3001#originalText","id":"talk.ch3_4_3001","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"初击胜利的比试现在开始！","en":"...will now begin!","ja":"一本先取の手合わせを始める!"},"kind":"dialogue"},{"uid":"talk.ch3_4_3002#originalText","id":"talk.ch3_4_3002","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"另外，在双方同意之下， 两人皆使用真剑。","en":"As was mutually agreed upon, both will use real swords.","ja":"なお双方の合意により両者ともに実剣を使用する"},"kind":"dialogue"},{"uid":"talk.ch3_4_3003#originalText","id":"talk.ch3_4_3003","speaker":{"cn":"观众席","en":"Audience","ja":"客席"},"text":{"cn":"喔喔，真剑？ 真的假的？","en":"Whoa! Real swords? Is this really happening?","ja":"おおっ、実剣? 本当かよ"},"kind":"dialogue"},{"uid":"talk.ch3_4_3004#originalText","id":"talk.ch3_4_3004","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"哎唷，边境那边有把剑 涂上墨汁的风俗吗， 莱欧斯同学！","en":"Oh? Raios, do wildlings paint their swords with ink in the hinterlands?","ja":"おやおや、辺境では剣に墨を塗る風習でもあるんですかなぁライオス殿!"},"kind":"dialogue"},{"uid":"talk.ch3_4_3005#originalText","id":"talk.ch3_4_3005","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"别这么说嘛，温贝尔。随侍大人太忙了，没空拭剑吧。","en":"Go easy on him, Humbert. Pages must be too busy to polish their swords.","ja":"そう言ってやるな、ウンベール傍付き殿は忙しくて、剣を磨くひまもないのだろうさ"},"kind":"dialogue"},{"uid":"talk.ch3_4_3006#originalText","id":"talk.ch3_4_3006","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"开始！","en":"Fight!","ja":"始め!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4000#originalText","id":"talk.ch3_4_4000","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"是海伊‧瑙鲁基亚流《天山烈波》的 起手式。他居然用了秘藏奥义。","en":"He's using the High-Norkian style stance for Mountain-Splitting Wave...","ja":"ハイ・ノルキア流《天山烈波》の構え秘奥義を使うとはな"},"kind":"dialogue"},{"uid":"talk.ch3_4_4100#originalText","id":"talk.ch3_4_4100","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（那是双手剑单发重突进技，《雪崩》。）","en":"(That's a two-handed single rush skill, Avalanche.)","ja":"(あれは両手剣単発重突進技《アバランシュ》)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4101#originalText","id":"talk.ch3_4_4101","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（而且，不是单纯的《雪崩》，应该因想像力而威力大增了。）","en":"(This is no ordinary Avalanche. It's boosted by his mental state.)","ja":"(しかもただの《アバランシュ》じゃないイメージの力で威力が増大されているはず)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4102#originalText","id":"talk.ch3_4_4102","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（可是，我不能闪避。）","en":"(I can't dodge it.)","ja":"(でも避けるわけにはいかない)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4103#originalText","id":"talk.ch3_4_4103","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（就算是为了遵守对莉娜学姊的承诺，我也得接下他的一击。）","en":"(I have to counter his attack. I have to keep my promise to Liena.)","ja":"(リーナ先輩との約束を果たすためにもやつの一撃を受けきらなくては)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4104#originalText","id":"talk.ch3_4_4104","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（我就多挥几剑……用纵砍四连击技《垂直四方斩》来分胜负。）","en":"(I'll repay his strike with four of my own...the Vertical Square technique.)","ja":"(こちらは手数で……縦斬り四連撃《バーチカル・スクエア》で、勝負だ)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4105#originalText","id":"talk.ch3_4_4105","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"喝啊啊！！","en":"Yahhh!!","ja":"カァァッ!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4106#originalText","id":"talk.ch3_4_4106","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喝啊啊！！","en":"Yahhh!!","ja":"ゼァァッ!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4300#originalText","id":"talk.ch3_4_4300","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"挡下来了……！？","en":"Kirito blocked it?!","ja":"止めた……!?"},"kind":"dialogue"},{"uid":"talk.ch3_4_4300_1#originalText","id":"talk.ch3_4_4300_1","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"我果然没有搞错……你就是我必须打倒的强者！","en":"I was right all along... You're a powerful opponent I must crush!","ja":"やはり……俺は間違っていなかったお前こそ、俺が食らうべき強者だ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4300_2#originalText","id":"talk.ch3_4_4300_2","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"竟然可以把我逼退到这个地步……桐人练士，你的强大超乎我的想像……","en":"I'm surprised you can keep up with me... You're stronger than I thought, Trainee Kirito.","ja":"俺をここまで追い込むとは……想像以上の強さだな、キリト練士……"},"kind":"dialogue"},{"uid":"talk.ch3_4_4301#originalText","id":"talk.ch3_4_4301","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（只要撑过去…… 我还有第四击！）","en":"(If I can get past this... I still have my fourth hit!)","ja":"(これをしのげば……俺にはまだ四撃目がある!)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4301_1#originalText","id":"talk.ch3_4_4301_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"很不巧，我可不会这么简单就被你打倒。","en":"Hate to disappoint you, but I'm going down without a fight.","ja":"あいにく、こっちはそう簡単に食われてやるつもりはないんでね"},"kind":"dialogue"},{"uid":"talk.ch3_4_4301_2#originalText","id":"talk.ch3_4_4301_2","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"但是，赌上利邦提家的荣耀，我不能输在这里！","en":"However, on the pride of the Levantein family, I won't lose here!","ja":"だが、リーバンテイン家の誇りにかけて俺は負けるわけにはいかないのだ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4302#originalText","id":"talk.ch3_4_4302","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（……！？ 这个是涡罗所背负的 利邦提家的……？）","en":"(Is this... the power of House Levantein, that Volo bears?)","ja":"(……!? これは、ウォロが背負っているリーバンテイン家の……?)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4303#originalText","id":"talk.ch3_4_4303","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"（这就是他如此强大的 想像力源头吗……！）","en":"(So this is the source of his imagination, his strength!)","ja":"(これがやつの強さのイメージの力の源か……!)"},"kind":"dialogue"},{"uid":"talk.ch3_4_4304#originalText","id":"talk.ch3_4_4304","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"喔喔喔喔！","en":"Grrraaaah!","ja":"おおおお!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4305#originalText","id":"talk.ch3_4_4305","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我也是……","en":"But I...","ja":"俺だって……"},"kind":"dialogue"},{"uid":"talk.ch3_4_4306#originalText","id":"talk.ch3_4_4306","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"绝对不能输在这里！","en":"I can't afford to lose now!","ja":"ここで、負けられないんだ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4307#originalText","id":"talk.ch3_4_4307","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔……喔喔喔喔喔喔喔！！","en":"G...grrraaaah!!","ja":"お……おおおおおおおッ!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_4308#originalText","id":"talk.ch3_4_4308","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"！？ 什么……！剑……变大了……！？","en":"What?! His sword...grew?!","ja":"!? な……!剣が……大きく……!?"},"kind":"dialogue"},{"uid":"talk.ch3_4_5051#originalText","id":"talk.ch3_4_5051","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"发自于内心的意念……《心意》……","en":"Intention from the soul... \"Will.\"","ja":"心からいずる意志……《シンイ》……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5052#originalText","id":"talk.ch3_4_5052","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……拜托。把你们的力量……天命， 分一点给我吧。","en":"Please...please share just a little bit of your power... of your life.","ja":"……頼む……力を……命をほんの少しだけ分けてくれ"},"kind":"dialogue"},{"uid":"talk.ch3_4_5053#originalText","id":"talk.ch3_4_5053","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"想像花的生命力透过我这个导线， 注入赛菲利雅的根部……","en":"Imagine the flowers...sending their life force into the Zephyria roots through me...","ja":"花の生命力が俺を導線としてゼフィリアの根に流れ込むようイメージするんだ……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5054#originalText","id":"talk.ch3_4_5054","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……！！","en":"...!!!","ja":"……!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_5054_2#originalText","id":"talk.ch3_4_5054_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"赛菲利雅的茎…… 从断掉的地方长出来了……","en":"The Zephyria stems... They're growing from where they were broken.","ja":"ゼフィリアの茎が……折られたところから伸びていく……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5055#originalText","id":"talk.ch3_4_5055","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是花蕾……花蕾又长出来了……！！","en":"It's budding... It's budding again!","ja":"蕾だ……蕾がまた……!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_5056#originalText","id":"talk.ch3_4_5056","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"刚才的声音是……","en":"Who was that voice...?","ja":"さっきの声は……"},"kind":"dialogue"},{"uid":"talk.ch3_4_5057#originalText","id":"talk.ch3_4_5057","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"…………谢谢。","en":"Thank you, whoever you are.","ja":"…………ありがとう"},"kind":"dialogue"},{"uid":"talk.ch3_4_6000#originalText","id":"talk.ch3_4_6000","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"人界历380年 3月底 修剑士毕业检定比试","en":"Late March, 380 HEC","ja":"人界暦380年 3月末修剣士卒業検定試合"},"kind":"caption"},{"uid":"talk.ch3_4_6001#originalText","id":"talk.ch3_4_6001","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"…………喝啊啊！！","en":"Yahhh!!","ja":"…………カァァッ!!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6002#originalText","id":"talk.ch3_4_6002","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"喔喔喔喔！","en":"Grrraaaah!!","ja":"おおおおっ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6003#originalText","id":"talk.ch3_4_6003","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"呀啊啊啊啊！","en":"Yahhh!!","ja":"やああああっ!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6004#originalText","id":"talk.ch3_4_6004","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"……呜！","en":"Oof!!","ja":"……う!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6005#originalText","id":"talk.ch3_4_6005","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"胜负已定！","en":"Match set!!","ja":"勝負あり!"},"kind":"dialogue"},{"uid":"talk.ch3_4_6006#originalText","id":"talk.ch3_4_6006","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就这样，莉娜学姊──","en":"And thus, Liena graduated...","ja":"こうしてリーナ先輩は――"},"kind":"dialogue"},{"uid":"talk.ch3_4_6007#originalText","id":"talk.ch3_4_6007","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"以北圣托利亚修剑学院第一名的成绩 毕业了。","en":"Top-rank, from North Centoria Academy of Swordcraft.","ja":"北セントリア修剣学院を第1位の成績で卒業していった"},"kind":"dialogue"},{"uid":"talk.ch3_4_6008#originalText","id":"talk.ch3_4_6008","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"──然后，我和尤吉欧在修剑士检定考 拿下第五名和第六名的成绩，晋级为上级修剑士。","en":"Eugeo and I passed our ranking examinations at 5th and 6th, advancing us to Elite Disciples.","ja":"――そして俺とユージオは、修剣士検定試験を5位と6位の成績で終え、上級修剣士として進級した"},"kind":"dialogue"}]};
